const REQUIRED = {
  acquire_lock: ['post_id', 'execution_id'],
  release_lock: ['post_id', 'execution_id'],
  log_audit: ['entity_type', 'audit_action', 'execution_id'],
  sync_draft: ['entity', 'record'],
  record_cost: ['post_id', 'execution_id', 'step', 'provider', 'model'],
  check_budget: ['post_id'],
  record_verification: ['content_id', 'content_hash', 'actor_user_id', 'decision', 'execution_id', 'notes', 'evidence'],
  record_reviewer_decision: ['content_id', 'content_hash', 'actor_user_id', 'decision', 'execution_id'],
  record_publisher_authorization: ['content_id', 'content_hash', 'actor_user_id', 'decision', 'execution_id'],
  record_admin_decision: ['content_id', 'content_hash', 'actor_user_id', 'decision', 'execution_id'],
  record_revision: ['content_id', 'content_hash', 'new_record', 'actor_user_id', 'execution_id'],
  claim_publish: ['destination', 'execution_id'],
  record_publish_result: ['attempt_id', 'execution_id', 'outcome']
};
// Deprecated name kept so existing callers keep working; it gets the same draft-only rules.
const ALIASES = { sync_record: 'sync_draft' };
const STATE_CHANGES = {
  release_lock: 'release_lock',
  log_audit: 'log_audit',
  sync_draft: 'sync_draft',
  record_verification: 'decision',
  record_reviewer_decision: 'decision',
  record_publisher_authorization: 'decision',
  record_admin_decision: 'decision',
  record_revision: 'revision',
  claim_publish: 'claim_publish',
  record_publish_result: 'publish_result'
};
const DECISIONS = {
  record_verification: { stage: 'verification', values: { verified: 'Verified', rejected: 'Rejected' } },
  record_reviewer_decision: { stage: 'reviewer', values: { approved: 'Approved', rejected: 'Rejected', revision_requested: 'Revision Requested' } },
  record_publisher_authorization: { stage: 'publisher', values: { authorized: 'Authorized', declined: 'Declined' } },
  record_admin_decision: { stage: 'admin', values: { approved: 'Approved', rejected: 'Rejected' } }
};
const PROTECTED_FIELDS = ['reviewer_name', 'reviewer_decision', 'reviewer_at', 'reviewer_user_id', 'reviewer_notes', 'publisher_name', 'publisher_authorization', 'publisher_at', 'publisher_user_id', 'admin_name', 'admin_approval', 'admin_at', 'admin_user_id', 'approved_hash', 'approved_version', 'approved_at', 'scheduled_for', 'published_at', 'linkedin_urn', 'post_url', 'superseded_by', 'verification_required', 'verified_by_user_id', 'verified_at', 'verification_notes', 'verification_evidence', 'verified_hash', 'verification_outcome'];
const PROTECTED_TOPIC_STATUSES = ['approved', 'scheduled', 'publishing', 'published'];
const DRAFT_CONTENT_STATUSES = ['Draft', 'Pending Review', 'Needs Human Verification', 'Validation Failed', 'Generation Failed', 'Persistence Failed'];
const REVISION_STATUSES = ['Pending Review', 'Needs Human Verification'];
const blank = v => v === undefined || v === null || (typeof v === 'string' && v.trim() === '') || (typeof v === 'object' && !Array.isArray(v) && Object.keys(v).length === 0);
const toObject = (v, label) => {
  let o = v;
  if (typeof o === 'string') {
    try { o = JSON.parse(o); } catch (e) { throw new Error(label + ' is not valid JSON'); }
  }
  if (!o || typeof o !== 'object' || Array.isArray(o)) throw new Error(label + ' must be an object');
  return o;
};

return $input.all().map((item, i) => {
  const r = Object.assign({}, item.json);
  let action = String(r.action || '').trim().toLowerCase();
  if (ALIASES[action]) { r.requested_action = action; action = ALIASES[action]; }
  if (!REQUIRED[action]) throw new Error('DB Gateway: unknown action "' + r.action + '"');
  r.action = action;
  r.route = STATE_CHANGES[action] ? 'state_change' : action;
  r.gov_route = STATE_CHANGES[action] || '';
  r.workflow_name = blank(r.workflow_name) ? '' : String(r.workflow_name);
  if (action === 'log_audit' && blank(r.entity_id)) r.entity_id = r.post_id;
  const missing = REQUIRED[action].filter(k => blank(r[k]));
  if (action === 'log_audit' && blank(r.entity_id)) missing.push('entity_id');
  if (missing.length) throw new Error('DB Gateway ' + action + ': missing ' + missing.join(', '));

  if (action === 'acquire_lock') {
    const ttl = blank(r.ttl_minutes) ? 30 : Number(r.ttl_minutes);
    if (!Number.isInteger(ttl) || ttl < 1 || ttl > 120) throw new Error('DB Gateway acquire_lock: ttl_minutes must be a whole number from 1 to 120');
    r.ttl_minutes = ttl;
  }

  if (action === 'sync_draft') {
    if (!['topic', 'content'].includes(r.entity)) throw new Error('DB Gateway sync_draft: entity must be topic or content');
    const rec = toObject(r.record, 'DB Gateway sync_draft: record');
    const blocked = Object.keys(rec).filter(k => PROTECTED_FIELDS.includes(k));
    if (blocked.length) throw new Error('DB Gateway sync_draft: approval, verification and publishing fields need their own action (' + blocked.join(', ') + ')');
    const status = String(rec.status || '').trim();
    if (r.entity === 'topic' && PROTECTED_TOPIC_STATUSES.includes(status.toLowerCase())) throw new Error('DB Gateway sync_draft: topic status "' + status + '" can only be set by the approval or publishing actions');
    if (r.entity === 'content' && status && !DRAFT_CONTENT_STATUSES.includes(status)) throw new Error('DB Gateway sync_draft: content status "' + status + '" is not a draft status (allowed: ' + DRAFT_CONTENT_STATUSES.join(', ') + ')');
    const idKey = r.entity === 'topic' ? 'post_id' : 'content_id';
    if (blank(rec[idKey])) throw new Error('DB Gateway sync_draft: record.' + idKey + ' is required');
    if (r.entity === 'content' && rec.post_text !== undefined && String(rec.post_text).length > 1250) throw new Error('DB Gateway sync_draft: post_text is over 1,250 characters');
    r.record = rec;
  }

  if (action === 'record_cost') {
    const cost = Number(r.cost_usd);
    if (!Number.isFinite(cost) || cost < 0) throw new Error('DB Gateway record_cost: cost_usd must be a number of 0 or more');
    r.cost_usd = cost;
    r.input_tokens = Math.max(0, Math.round(Number(r.input_tokens) || 0));
    r.output_tokens = Math.max(0, Math.round(Number(r.output_tokens) || 0));
    const usage = String(r.usage_type || 'estimated').trim().toLowerCase();
    if (!['actual', 'estimated'].includes(usage)) throw new Error('DB Gateway record_cost: usage_type must be actual or estimated');
    r.usage_type = usage;
    r.pricing_version = blank(r.pricing_version) ? 'unversioned' : String(r.pricing_version);
    r.content_id = blank(r.content_id) ? '' : String(r.content_id);
    r.idempotency_key = blank(r.idempotency_key) ? [r.post_id, r.execution_id, r.step, r.charge_no || 1].join(':') : String(r.idempotency_key);
  }

  if (DECISIONS[action] || action === 'record_revision') {
    r.content_hash = String(r.content_hash).trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(r.content_hash)) throw new Error('DB Gateway ' + action + ': content_hash must be the 64-character SHA-256 hex of the exact post text');
    r.actor_user_id = String(r.actor_user_id).trim();
    r.actor_channel = blank(r.actor_channel) ? 'unspecified' : String(r.actor_channel);
  }

  if (DECISIONS[action]) {
    const cfg = DECISIONS[action];
    const key = String(r.decision).trim().toLowerCase().replace(/[ -]+/g, '_');
    if (!cfg.values[key]) throw new Error('DB Gateway ' + action + ': decision must be one of ' + Object.keys(cfg.values).join(', '));
    r.stage = cfg.stage;
    r.decision = key;
    r.decision_label = cfg.values[key];
    r.notes = blank(r.notes) ? '' : String(r.notes);
    r.evidence_json = JSON.stringify(blank(r.evidence) ? {} : (typeof r.evidence === 'string' ? { text: r.evidence } : r.evidence));
    r.idempotency_key = [r.content_id, cfg.stage, r.content_hash, r.actor_user_id, key].join(':');
  }

  if (action === 'record_revision') {
    const nr = toObject(r.new_record, 'DB Gateway record_revision: new_record');
    const blocked = Object.keys(nr).filter(k => PROTECTED_FIELDS.includes(k) || ['post_id', 'version', 'parent_content_id', 'destination', 'language', 'variation_label'].includes(k));
    if (blocked.length) throw new Error('DB Gateway record_revision: new_record cannot set ' + blocked.join(', ') + ' (taken from the parent version or set by other actions)');
    if (blank(nr.content_id)) throw new Error('DB Gateway record_revision: new_record.content_id is required');
    if (String(nr.content_id) === String(r.content_id)) throw new Error('DB Gateway record_revision: the new version needs a new content_id');
    const text = String(nr.post_text || '');
    if (!text.trim()) throw new Error('DB Gateway record_revision: new_record.post_text is required');
    if (text.length > 1250) throw new Error('DB Gateway record_revision: post_text is ' + text.length + ' characters (max 1,250)');
    nr.status = blank(nr.status) ? 'Pending Review' : String(nr.status);
    if (!REVISION_STATUSES.includes(nr.status)) throw new Error('DB Gateway record_revision: new version status must be Pending Review or Needs Human Verification');
    r.change_summary = blank(nr.status_note) ? '' : String(nr.status_note);
    r.new_record = nr;
  }

  if (action === 'claim_publish') {
    const d = String(r.destination).trim().toLowerCase();
    if (!['personal', 'company'].includes(d)) throw new Error('DB Gateway claim_publish: destination must be Personal or Company');
    r.destination = d === 'personal' ? 'Personal' : 'Company';
    r.slot_label = blank(r.slot_label) ? '' : String(r.slot_label);
  }

  if (action === 'record_publish_result') {
    r.attempt_id = String(r.attempt_id).trim().toLowerCase();
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(r.attempt_id)) throw new Error('DB Gateway record_publish_result: attempt_id must be the UUID returned by claim_publish');
    const o = String(r.outcome).trim().toLowerCase();
    if (!['published', 'failed', 'unknown'].includes(o)) throw new Error('DB Gateway record_publish_result: outcome must be published, failed (LinkedIn explicitly refused) or unknown (timeout or no response)');
    r.outcome = o;
    if (o === 'published' && blank(r.linkedin_urn)) throw new Error('DB Gateway record_publish_result: linkedin_urn is required when outcome is published');
    r.linkedin_urn = blank(r.linkedin_urn) ? '' : String(r.linkedin_urn);
    r.post_url = blank(r.post_url) ? '' : String(r.post_url);
    r.error_details = blank(r.error_details) ? '' : String(r.error_details).slice(0, 2000);
  }

  return { json: r, pairedItem: { item: i } };
});

